// Authored integration demo; implementation is installed from the pinned official source.
import Component from '../../../.upstream/src/ts-default/Components/Counter/Counter';
import { palette } from '../../shared/demo-support';
import { useState } from "react";
// 真实数字滚轮由外部state驱动，按钮改变数字而不是仅展示静态值。

export default function CounterDemo() {
  const [value, setValue] = useState(/*__AW_STATE_state.value__*/);
  return (
    <div className="aw-demo-stage" style={{ width: '100%', minHeight: 340, position: 'relative', display: 'grid', placeItems: 'center', padding: 24, color: palette.ink }}>
      <div style={{ display: 'grid', gap: 24, placeItems: 'center' }}><Component value={value}            /*__AW_PROPS_t0__*/  /><div style={{ display: 'flex', gap: 12 }}><button  className="aw-button" data-variant="secondary" onClick={() => setValue(number => Math.max(0, number - 1))} /*__AW_PROPS_t1__*/ >减少</button><button  className="aw-button" data-variant="primary" onClick={() => setValue(number => number + 1)} /*__AW_PROPS_t2__*/ >增加</button></div><p aria-live="polite" style={{ color: palette.muted }}>当前数值：{value}</p></div>
    </div>
  );
}

props.defaultExpression:
[...value.toString()].map((ch, i, a) => {
    if (ch === '.') {
      return '.';
    }
    const dotIndex = a.indexOf('.');
    const isInteger = dotIndex === -1;

    const exponent = isInteger ? a.length - i - 1 : i < dotIndex ? dotIndex - i - 1 : -(i - dotIndex);

    return 10 ** exponent;
  })
